"use client";

/**
 * Multi-account authentication + identity provider.
 *
 * Security model (deliberately local-first, zero infrastructure):
 *  • Every account gets a REAL 2048-bit RSA-OAEP (encryption) and RSA-PSS
 *    (signing) key pair generated by Web Crypto in this browser.
 *  • Only the PUBLIC halves are published to the server directory
 *    (`POST /api/keys`) so other accounts can address encrypted mail.
 *  • The private halves + certificates live in `localStorage`, per account, so
 *    sessions survive a `npm run dev` restart. ⚠ Demo trade-off: a production
 *    client must wrap these with a passphrase/OS keystore.
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import type { DirectoryEntry, LocalAccount } from "@/lib/types";
import {
  buildPgpLikeCertificate,
  buildX509LikeCertificate,
  generateUserKeyPairs,
} from "@/lib/crypto/webcrypto";
import { jwkFingerprint } from "@/lib/crypto";
import {
  registerPublicKey,
  tryFetchDirectoryEntry,
} from "@/lib/api/emailClient";
import { DEMO_PROFILES, type DemoProfileId } from "@/lib/constants";
import { useSecurityMode } from "@/store/SecurityModeContext";
import { useTransport } from "@/store/TransportContext";

const ACCOUNTS_KEY = "cryptoshield.accounts.v2";
const SESSION_KEY = "cryptoshield.session.v2";

const AVATARS = ["🛰️", "🦊", "🧿", "⚡", "🛡️", "🕵️", "🚀", "🧬", "🔮", "🦉", "🐙", "🧠"];

export type AuthStatus = "loading" | "generating" | "ready" | "signedOut" | "error";

export interface RegisterInput {
  name: string;
  email: string;
  role?: string;
}

interface AuthContextValue {
  status: AuthStatus;
  /** The signed-in account (null until authentication). */
  account: LocalAccount | null;
  /** Alias kept for components that speak in "profiles". */
  profile: LocalAccount | null;
  /** Accounts stored on this device (available for one-click sign-in). */
  accounts: LocalAccount[];
  /** True once the active account's public keys are in the server directory. */
  registered: boolean;
  /** Human-readable failure from the last auth operation. */
  error: string | null;
  /** In-flight auth operation (key generation takes ~1s). */
  busy: boolean;
  signIn: (email: string) => Promise<boolean>;
  register: (input: RegisterInput) => Promise<boolean>;
  quickDemo: (id: DemoProfileId) => Promise<boolean>;
  guest: () => Promise<boolean>;
  signOut: () => void;
  forget: (email: string) => void;
  /** Directory lookup for a typed address (null when unknown). */
  lookup: (email: string) => Promise<DirectoryEntry | null>;
  /** Rotate an account's keys on THIS device (server directory updated). */
  resetDeviceKeys: (email: string, name?: string) => Promise<boolean>;
  clearError: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
}

function pickAvatar(email: string): string {
  let hash = 0;
  for (let i = 0; i < email.length; i += 1) hash = (hash * 31 + email.charCodeAt(i)) >>> 0;
  return AVATARS[hash % AVATARS.length];
}

function readAccounts(): LocalAccount[] {
  try {
    if (typeof window === "undefined") return [];
    const raw = window.localStorage.getItem(ACCOUNTS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as LocalAccount[];
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (entry) =>
        typeof entry?.email === "string" &&
        !!entry.keyPair?.encryption?.privateKey &&
        !!entry.keyPair?.signing?.privateKey,
    );
  } catch {
    return [];
  }
}

function writeAccounts(accounts: LocalAccount[]): void {
  try {
    window.localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
  } catch (cause) {
    console.warn("[CryptoShield] could not persist accounts:", cause);
  }
}

function readSession(): string | null {
  try {
    if (typeof window === "undefined") return null;
    return window.localStorage.getItem(SESSION_KEY);
  } catch {
    return null;
  }
}

function writeSession(email: string | null): void {
  try {
    if (email) window.localStorage.setItem(SESSION_KEY, email);
    else window.localStorage.removeItem(SESSION_KEY);
  } catch {
    // Ignore storage failures — the in-memory session still works.
  }
}

/** Generate a complete account (key pairs + certificates) entirely client-side. */
async function createAccount(input: {
  name: string;
  email: string;
  role: string;
  avatar?: string;
}): Promise<LocalAccount> {
  const keyPair = await generateUserKeyPairs();
  const [x509, pgp] = await Promise.all([
    buildX509LikeCertificate(keyPair.signing, input.name, input.email),
    buildPgpLikeCertificate(keyPair.signing, input.name, input.email),
  ]);
  const fingerprint = await jwkFingerprint(keyPair.signing.publicKey);

  return {
    id: `${input.email.split("@")[0]}-${fingerprint.slice(0, 6).toLowerCase()}`,
    displayName: input.name,
    email: input.email,
    role: input.role,
    avatar: input.avatar ?? pickAvatar(input.email),
    keyPair,
    certificate: { x509, pgp },
    fingerprint,
    createdAt: Date.now(),
  };
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const { mode } = useSecurityMode();
  const { recordPacket } = useTransport();

  const [accounts, setAccounts] = useState<LocalAccount[]>([]);
  const [account, setAccount] = useState<LocalAccount | null>(null);
  const [status, setStatus] = useState<AuthStatus>("loading");
  const [registered, setRegistered] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // Don't republish the same key material over and over.
  const publishedRef = useRef<Set<string>>(new Set());

  /** Publish one account's PUBLIC keys once; safe to call repeatedly. */
  const ensurePublished = useCallback(
    async (target: LocalAccount): Promise<boolean> => {
      const key = `${target.email}:${target.fingerprint}`;
      if (publishedRef.current.has(key)) return true;
      try {
        await registerPublicKey(
          target.email,
          target.keyPair.encryption.publicKey,
          target.keyPair.signing.publicKey,
          mode,
          recordPacket,
          { name: target.displayName, role: target.role },
        );
        publishedRef.current.add(key);
        return true;
      } catch (cause) {
        console.error("[CryptoShield] directory publish failed:", cause);
        return false;
      }
    },
    [mode, recordPacket],
  );

  // ── Restore the device's accounts + last session ──────────────────
  useEffect(() => {
    const stored = readAccounts();
    setAccounts(stored);

    const session = readSession();
    const restored = session
      ? stored.find((entry) => entry.email === normalizeEmail(session))
      : undefined;

    if (restored) {
      setAccount(restored);
      setStatus("ready");
    } else {
      setStatus("signedOut");
    }
  }, []);

  // ── Keep the directory in sync with EVERY identity in the local vault ──
  // Publishing only the active account would leave mail addressed to another
  // local profile encrypted to a stale/placeholder key (unreadable later), so
  // the whole vault is registered — public material only.
  useEffect(() => {
    if (!account) {
      setRegistered(false);
      return;
    }

    const activeKey = `${account.email}:${account.fingerprint}`;
    setRegistered(publishedRef.current.has(activeKey));

    const targets = accounts.some((entry) => entry.email === account.email)
      ? accounts
      : [...accounts, account];

    let cancelled = false;
    (async () => {
      for (const target of targets) {
        const ok = await ensurePublished(target);
        if (cancelled) return;
        if (target.email === account.email) {
          setRegistered(ok);
          if (!ok) {
            setError(
              "Could not publish your public keys to the directory. Secure sending is unavailable until this succeeds.",
            );
          }
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [account, accounts, ensurePublished]);

  const persistAccount = useCallback((next: LocalAccount) => {
    setAccounts((current) => {
      const merged = [
        next,
        ...current.filter((entry) => entry.email !== next.email),
      ].sort((a, b) => a.createdAt - b.createdAt);
      writeAccounts(merged);
      return merged;
    });
  }, []);

  const activate = useCallback((next: LocalAccount) => {
    setAccount(next);
    setStatus("ready");
    setError(null);
    writeSession(next.email);
  }, []);

  const signIn = useCallback(
    async (rawEmail: string): Promise<boolean> => {
      const email = normalizeEmail(rawEmail);
      setError(null);

      if (!isValidEmail(email)) {
        setError("Enter a valid email address.");
        return false;
      }

      const existing = readAccounts().find((entry) => entry.email === email);
      if (existing) {
        activate(existing);
        return true;
      }

      // The account may exist in the directory from another device. We cannot
      // recover its private key, so signing in here must rotate device keys.
      setError(
        "No private keys for that address on this device. Use “Generate keys on this device” to take over the account.",
      );
      return false;
    },
    [activate],
  );

  const register = useCallback(
    async ({ name, email: rawEmail, role }: RegisterInput): Promise<boolean> => {
      const email = normalizeEmail(rawEmail);
      const cleanName = name.trim();
      setError(null);

      if (cleanName.length < 2) {
        setError("Enter your name (at least 2 characters).");
        return false;
      }
      if (!isValidEmail(email)) {
        setError("Enter a valid email address.");
        return false;
      }
      if (readAccounts().some((entry) => entry.email === email)) {
        setError("That account already exists on this device — sign in instead.");
        return false;
      }

      setBusy(true);
      setStatus("generating");
      try {
        const created = await createAccount({
          name: cleanName,
          email,
          role: role?.trim() || "Member",
        });
        activate(created);
        persistAccount(created);
        return true;
      } catch (cause) {
        console.error("[CryptoShield] registration failed:", cause);
        setError(cause instanceof Error ? cause.message : "Could not generate your keys.");
        setStatus(account ? "ready" : "signedOut");
        return false;
      } finally {
        setBusy(false);
      }
    },
    [account, activate, persistAccount],
  );

  const resetDeviceKeys = useCallback(
    async (rawEmail: string, name?: string): Promise<boolean> => {
      const email = normalizeEmail(rawEmail);
      setError(null);
      setBusy(true);
      try {
        const created = await createAccount({
          name: name?.trim() || email.split("@")[0],
          email,
          role: "Member",
        });
        activate(created);
        persistAccount(created);
        return true;
      } catch (cause) {
        setError(
          cause instanceof Error ? cause.message : "Could not generate device keys.",
        );
        return false;
      } finally {
        setBusy(false);
      }
    },
    [activate, persistAccount],
  );

  const quickDemo = useCallback(
    async (id: DemoProfileId): Promise<boolean> => {
      const demo = DEMO_PROFILES.find((entry) => entry.id === id);
      if (!demo) return false;

      setBusy(true);
      setError(null);
      try {
        // Provision the WHOLE demo roster, not just the selected profile.
        // Mail is addressed to a directory key, so every claimable demo
        // identity must have its browser-held key pair published BEFORE any
        // encrypted mail is sent to it.
        const vault = readAccounts();
        const missing = DEMO_PROFILES.filter(
          (profile) => !vault.some((entry) => entry.email === profile.email),
        );
        const created = await Promise.all(
          missing.map((profile) =>
            createAccount({
              name: profile.name,
              email: profile.email,
              role: profile.role,
              avatar: profile.avatar,
            }),
          ),
        );

        const next = [...vault, ...created].sort((a, b) => a.createdAt - b.createdAt);
        if (created.length > 0) {
          writeAccounts(next);
          setAccounts(next);
        }

        const target = next.find((entry) => entry.email === demo.email);
        if (!target) throw new Error("Could not provision the demo identity");

        const demoAccounts = next.filter((entry) =>
          DEMO_PROFILES.some((profile) => profile.email === entry.email),
        );
        await Promise.all(demoAccounts.map(ensurePublished));

        activate(target);
        return true;
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "Could not create the demo profile.");
        return false;
      } finally {
        setBusy(false);
      }
    },
    [activate, ensurePublished],
  );

  const guest = useCallback(async (): Promise<boolean> => {
    const suffix = Math.random().toString(36).slice(2, 8);
    return register({
      name: "Guest Operator",
      email: `guest-${suffix}@cryptoshield.dev`,
      role: "Guest",
    });
  }, [register]);

  const signOut = useCallback(() => {
    setAccount(null);
    setStatus("signedOut");
    setRegistered(false);
    setError(null);
    writeSession(null);
  }, []);

  const forget = useCallback(
    (email: string) => {
      const normalized = normalizeEmail(email);
      setAccounts((current) => {
        const next = current.filter((entry) => entry.email !== normalized);
        writeAccounts(next);
        return next;
      });
      if (account?.email === normalized) signOut();
    },
    [account, signOut],
  );

  const lookup = useCallback(async (rawEmail: string): Promise<DirectoryEntry | null> => {
    const email = normalizeEmail(rawEmail);
    if (!isValidEmail(email)) return null;
    // Routed through the API client so static (GitHub Pages) builds resolve
    // against the localStorage relay instead of a server that isn't there.
    return tryFetchDirectoryEntry(email);
  }, []);

  const clearError = useCallback(() => setError(null), []);

  const value = useMemo<AuthContextValue>(
    () => ({
      status,
      account,
      profile: account,
      accounts,
      registered,
      error,
      busy,
      signIn,
      register,
      quickDemo,
      guest,
      signOut,
      forget,
      lookup,
      resetDeviceKeys,
      clearError,
    }),
    [
      status,
      account,
      accounts,
      registered,
      error,
      busy,
      signIn,
      register,
      quickDemo,
      guest,
      signOut,
      forget,
      lookup,
      resetDeviceKeys,
      clearError,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/** Access the session + identity actions. Throws outside `AuthProvider`. */
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}
